SPLIT = re.compile(r"[\n\r,;]+")


def _numbers(text):
    return {part.strip() for part in SPLIT.split(text or "") if part.strip()}


def link_return_lines(apps, schema_editor):
    """Связывает строки старых возвратов покупателей со строками отгрузки-
    основания — только однозначно:

    * в основании одна строка этого товара — она;
    * серийный товар — строка, в номерах которой есть все номера возврата,
      если такая строка одна.

    Остальные строки остаются без связи. Серийный возврат с номерами из
    нескольких строк пересчёт распределяет по номерам (это тоже возврат «по
    строкам»). Возврат без строки и без номеров при нескольких строках
    товара считается «по отгрузке в целом»; если рядом есть возвраты по
    строкам, check_costs требует уточнить его («ТРЕБУЕТ РЕШЕНИЯ»). Ничего не
    угадывается.
    """
    return_line_model = apps.get_model("sales", "CustomerReturnLine")
    shipment_line_model = apps.get_model("sales", "ShipmentLine")
    product_model = apps.get_model("catalog", "Product")
    lines = return_line_model.objects.filter(shipment_line__isnull=True, document__shipment__isnull=False)
    for line in lines.select_related("document"):
        candidates = list(shipment_line_model.objects.filter(
            shipment_id=line.document.shipment_id, product_id=line.product_id).order_by("pk"))
        chosen = None
        if len(candidates) == 1:
            chosen = candidates[0]
        elif len(candidates) > 1:
            tracked = product_model.objects.filter(pk=line.product_id, track_serials=True).exists()
            numbers = _numbers(line.serial_numbers)
            if tracked and numbers:
                matching = [c for c in candidates if numbers <= _numbers(c.serial_numbers)]
                if len(matching) == 1:
                    chosen = matching[0]
        if chosen is not None:
            return_line_model.objects.filter(pk=line.pk).update(shipment_line=chosen)


